# Exact full-store equality fixture from Cathedral owned-bytes tests; no hash/fingerprint approximation.
HELPERS='machine fx_bytes_equal(a:&[u8;256],b:&[u8;256],i:u64,n:u64,prior:bool)\nterminates by(i,n)->Nat::BoundedDistance;\n->bool {let good:bool=fx_byte_equal(a,b,i,n);transition i<n {true -> fx_bytes_equal(a,b,i+1,n,prior && good) _ -> (prior)}}\nmachine fx_byte_equal(a:&[u8;256],b:&[u8;256],i:u64,n:u64)->bool {transition i<n && i<256 {true -> (a[i]==b[i]) _ -> (true)}}\nmachine fx_span(a:Span,b:Span)->bool {a.unit==b.unit && a.start==b.start && a.end==b.end}\nmachine fx_path(a:Path,b:Path)->bool {let good:bool=fx_segments(&a.segments,&b.segments,0,16,true);a.absolute==b.absolute && a.parents==b.parents && a.count==b.count && good}\nmachine fx_segments(a:&[u32;16],b:&[u32;16],i:u64,n:u64,prior:bool)\nterminates by(i,n)->Nat::BoundedDistance;\n->bool {let good:bool=fx_segment(a,b,i,n);transition i<n {true -> fx_segments(a,b,i+1,n,prior && good) _ -> (prior)}}\nmachine fx_segment(a:&[u32;16],b:&[u32;16],i:u64,n:u64)->bool {transition i<n && i<16 {true -> (a[i]==b[i]) _ -> (true)}}\nmachine fx_string(a:StringStorage,b:StringStorage)->bool {\n transition a {StringStorage::Source {string_source} -> source(string_source,b) StringStorage::Owned {string_owner} -> owned(string_owner,b)}\n state source(a:Span,b:StringStorage)->bool {transition b {StringStorage::Source {string_source} -> span(a,string_source) _ -> (false)}}\n state span(a:Span,b:Span)->bool {let good:bool=fx_span(a,b);good}\n state owned(a:u64,b:StringStorage)->bool {transition b {StringStorage::Owned {string_owner} -> (a==string_owner) _ -> (false)}}\n}\nmachine fx_buffer(a:BufferStorage,b:BufferStorage)->bool {\n transition a {BufferStorage::Source {declared_size,buffer_initializer} -> source(declared_size,buffer_initializer,b) BufferStorage::Owned {buffer_owner} -> owned(buffer_owner,b)}\n state source(size:u64,a:Span,b:BufferStorage)->bool {transition b {BufferStorage::Source {declared_size,buffer_initializer} -> span(size,a,declared_size,buffer_initializer) _ -> (false)}}\n state span(size:u64,a:Span,other:u64,b:Span)->bool {let good:bool=fx_span(a,b);size==other && good}\n state owned(a:u64,b:BufferStorage)->bool {transition b {BufferStorage::Owned {buffer_owner} -> (a==buffer_owner) _ -> (false)}}\n}\nmachine fx_value(a:Value,b:Value)->bool {transition a {\nValue::Uninitialized -> c_uninitialized(b)\nValue::Integer {number} -> c_integer(number,b)\nValue::String {string_storage} -> c_string(string_storage,b)\nValue::Buffer {buffer_storage} -> c_buffer(buffer_storage,b)\nValue::BufferField {backing_object,bit_offset,bit_length} -> c_bufferfield(backing_object,bit_offset,bit_length,b)\nValue::Package {first,count} -> c_package(first,count,b)\nValue::NameReference {name,scope} -> c_namereference(name,scope,b)\nValue::Reference {kind,object_id} -> c_reference(kind,object_id,b)\nValue::Method {flags,body} -> c_method(flags,body,b)\nValue::Device -> c_device(b)\nValue::Processor {id,address,length} -> c_processor(id,address,length,b)\nValue::PowerResource {system_level,order} -> c_powerresource(system_level,order,b)\nValue::ThermalZone -> c_thermalzone(b)\nValue::Mutex {sync_level} -> c_mutex(sync_level,b)\nValue::Event -> c_event(b)\nValue::OperationRegion {space,base,length,scope} -> c_operationregion(space,base,length,scope,b)\n}\nstate c_uninitialized(b:Value)->bool {transition b {Value::Uninitialized -> (true) _ -> (false)}}\nstate c_integer(a_number:u64,b:Value)->bool {transition b {Value::Integer {number} -> (a_number==number) _ -> (false)}}\nstate c_string(a_string_storage:StringStorage,b:Value)->bool {transition b {Value::String {string_storage} -> check_c_string(a_string_storage,string_storage) _ -> (false)}}\nstate check_c_string(a_string_storage:StringStorage,string_storage:StringStorage)->bool {let good_string_storage:bool=fx_string(a_string_storage,string_storage);good_string_storage}\nstate c_buffer(a_buffer_storage:BufferStorage,b:Value)->bool {transition b {Value::Buffer {buffer_storage} -> check_c_buffer(a_buffer_storage,buffer_storage) _ -> (false)}}\nstate check_c_buffer(a_buffer_storage:BufferStorage,buffer_storage:BufferStorage)->bool {let good_buffer_storage:bool=fx_buffer(a_buffer_storage,buffer_storage);good_buffer_storage}\nstate c_bufferfield(a_backing_object:u64,a_bit_offset:u64,a_bit_length:u64,b:Value)->bool {transition b {Value::BufferField {backing_object,bit_offset,bit_length} -> (a_backing_object==backing_object && a_bit_offset==bit_offset && a_bit_length==bit_length) _ -> (false)}}\nstate c_package(a_first:u64,a_count:u64,b:Value)->bool {transition b {Value::Package {first,count} -> (a_first==first && a_count==count) _ -> (false)}}\nstate c_namereference(a_name:Path,a_scope:Path,b:Value)->bool {transition b {Value::NameReference {name,scope} -> check_c_namereference(a_name,a_scope,name,scope) _ -> (false)}}\nstate check_c_namereference(a_name:Path,a_scope:Path,name:Path,scope:Path)->bool {let good_name:bool=fx_path(a_name,name);let good_scope:bool=fx_path(a_scope,scope);good_name && good_scope}\nstate c_reference(a_kind:ReferenceKind,a_object_id:u64,b:Value)->bool {transition b {Value::Reference {kind,object_id} -> (a_kind==kind && a_object_id==object_id) _ -> (false)}}\nstate c_method(a_flags:u8,a_body:Span,b:Value)->bool {transition b {Value::Method {flags,body} -> check_c_method(a_flags,a_body,flags,body) _ -> (false)}}\nstate check_c_method(a_flags:u8,a_body:Span,flags:u8,body:Span)->bool {let good_body:bool=fx_span(a_body,body);a_flags==flags && good_body}\nstate c_device(b:Value)->bool {transition b {Value::Device -> (true) _ -> (false)}}\nstate c_processor(a_id:u8,a_address:u32,a_length:u8,b:Value)->bool {transition b {Value::Processor {id,address,length} -> (a_id==id && a_address==address && a_length==length) _ -> (false)}}\nstate c_powerresource(a_system_level:u8,a_order:u16,b:Value)->bool {transition b {Value::PowerResource {system_level,order} -> (a_system_level==system_level && a_order==order) _ -> (false)}}\nstate c_thermalzone(b:Value)->bool {transition b {Value::ThermalZone -> (true) _ -> (false)}}\nstate c_mutex(a_sync_level:u8,b:Value)->bool {transition b {Value::Mutex {sync_level} -> (a_sync_level==sync_level) _ -> (false)}}\nstate c_event(b:Value)->bool {transition b {Value::Event -> (true) _ -> (false)}}\nstate c_operationregion(a_space:u8,a_base:u64,a_length:u64,a_scope:Path,b:Value)->bool {transition b {Value::OperationRegion {space,base,length,scope} -> check_c_operationregion(a_space,a_base,a_length,a_scope,space,base,length,scope) _ -> (false)}}\nstate check_c_operationregion(a_space:u8,a_base:u64,a_length:u64,a_scope:Path,space:u8,base:u64,length:u64,scope:Path)->bool {let good_scope:bool=fx_path(a_scope,scope);a_space==space && a_base==base && a_length==length && good_scope}\n}\nmachine fx_store(a:&ObjectStore,b:&ObjectStore)->bool {\n let objects:bool=fx_objects(a,b,0,64,true);let entries:bool=fx_entries(&a.space,&b.space,0,32,true);\n a.space.object_count==b.space.object_count && a.space.count==b.space.count && objects && entries\n}\nmachine fx_objects(a:&ObjectStore,b:&ObjectStore,i:u64,n:u64,prior:bool)\nterminates by(i,n)->Nat::BoundedDistance;\n->bool {let good:bool=fx_object(a,b,i,n);transition i<n {true -> fx_objects(a,b,i+1,n,prior && good) _ -> (prior)}}\nmachine fx_object(a:&ObjectStore,b:&ObjectStore,i:u64,n:u64)->bool {\n transition i<n && i<64 {true -> item(a,b,i) _ -> (true)}\n state item(a:&ObjectStore,b:&ObjectStore,i:u64)->bool {\n  let left:Object=a.space.objects[i];let right:Object=b.space.objects[i];let first:ByteBlock=a.bytes.blocks[i];let second:ByteBlock=b.bytes.blocks[i];\n  let payload:bool=fx_value(left.value,right.value);\n  let bytes:bool=fx_bytes_equal(&first.bytes,&second.bytes,0,256,true);\n  payload && bytes && left.has_next==right.has_next && left.next==right.next && first.initialized==second.initialized && first.length==second.length\n }\n}\nmachine fx_entries(a:&Namespace,b:&Namespace,i:u64,n:u64,prior:bool)\nterminates by(i,n)->Nat::BoundedDistance;\n->bool {let good:bool=fx_entry(a,b,i,n);transition i<n {true -> fx_entries(a,b,i+1,n,prior && good) _ -> (prior)}}\nmachine fx_entry(a:&Namespace,b:&Namespace,i:u64,n:u64)->bool {\n transition i<n && i<32 {true -> item(a.entries[i],b.entries[i]) _ -> (true)}\n state item(a:Entry,b:Entry)->bool {let path:bool=fx_path(a.path,b.path);path && a.has_level==b.has_level && a.level==b.level && a.has_object==b.has_object && a.object==b.object && a.alias==b.alias}\n}\n'
